/// <summary>
/// Document handler class for the Location Content page.
/// </summary>
[TFMTableName(tableStr(InventSum),staticMethodStr(MobConstants,LocationContent)),
    TFMDocumentType(classStr(TFMLookup), staticMethodStr(MobConstants,LocationContent), methodStr(MobDocLocationContent,lookupLocationContent )),
    TFMMenu(staticMethodStr(MobConstants,LocationContent),"@MobileWMS:MobileWMS164","@MobileWMS:MobileWMS164",resourceStr(MobLocationContentIcon),true,true,['MainMenu', 'Warehouse', 'Outbound'],true)
]
class MobDocLocationContent extends TFMDocumentHandler
{
    FieldName   fieldNameToOmit;
    NoYes       enableOmitField;

}

